#include <stdio.h>

int main(void) {
    int posti_liberi = 24;
    printf("Posti liberi iniziali: %d\n", posti_liberi);

    posti_liberi = 18;
    printf("Posti liberi dopo la pausa: %d\n", posti_liberi);

    posti_liberi = 0;
    printf("Posti liberi a fine giornata: %d\n", posti_liberi);
    return 0;
}

#include <stdio.h>

int main(void) {
    long codice_orbita = 1'450'000L;
    int anno_lancio = 2025;
    double quota_km = 824.5;
    char classe_orbita = 'P';
    bool attivo = true;

    printf("Codice orbita: %ld\n", codice_orbita);
    printf("Anno di lancio: %d\n", anno_lancio);
    printf("Quota (km): %f\n", quota_km);
    printf("Classe: %c\n", classe_orbita);
    printf("Attivo (1=vero, 0=falso): %d\n", attivo);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned int numero_pannelli = 12U;
    long long energia_totale_wh = 12'450'800LL;
    double potenza_kw = 4.35;
    double rendimento = 21.8;
    char classe_efficienza = 'A';

    printf("=== IMPIANTO FOTOVOLTAICO ===\n");
    printf("Pannelli installati : %6u\n", numero_pannelli);
    printf("Energia prodotta    : %lld Wh\n", energia_totale_wh);
    printf("Potenza nominale    : %6.2f kW\n", potenza_kw);
    printf("Rendimento          : %5.1f%%\n", rendimento);
    printf("Classe energetica   : %6c\n", classe_efficienza);
    return 0;
}

#include <stdio.h>

int main(void) {
    constexpr int LARGHEZZA_PIATTO_MM = 220;
    constexpr int ALTEZZA_MAX_MM = 250;
    constexpr double DIAMETRO_UGELLO_MM = 0.40;
    constexpr char PROFILO_QUALITA = 'M';

    const int TEMPERATURA_ESTRUSORE = 210;
    const bool VENTOLA_ATTIVA = true;

    printf("=== CONFIGURAZIONE STAMPANTE 3D ===\n");
    printf("Piatto (mm): %d x %d\n", LARGHEZZA_PIATTO_MM, ALTEZZA_MAX_MM);
    printf("Ugello (mm): %.2f\n", DIAMETRO_UGELLO_MM);
    printf("Profilo: %c\n", PROFILO_QUALITA);
    printf("Temperatura estrusore (C): %d\n", TEMPERATURA_ESTRUSORE);
    printf("Ventola attiva (1=vero, 0=falso): %d\n", VENTOLA_ATTIVA);
    return 0;
}

#include <limits.h>
#include <stddef.h>
#include <stdio.h>

int main(void) {
    const size_t DIM_CHAR = sizeof(char);
    const size_t DIM_BOOL = sizeof(bool);
    const size_t DIM_SHORT = sizeof(short);
    const size_t DIM_INT = sizeof(int);
    const size_t DIM_LLONG = sizeof(long long);
    const size_t DIM_DOUBLE = sizeof(double);

    printf("Bit per byte: %d\n", CHAR_BIT);
    printf("char       : %zu byte (signed: %d .. %d, unsigned max: %d)\n",
           DIM_CHAR, SCHAR_MIN, SCHAR_MAX, UCHAR_MAX);
    printf("bool       : %zu byte\n", DIM_BOOL);
    printf("short      : %zu byte (%d .. %d)\n", DIM_SHORT, SHRT_MIN, SHRT_MAX);
    printf("int        : %zu byte (%d .. %d, unsigned max: %u)\n",
           DIM_INT, INT_MIN, INT_MAX, UINT_MAX);
    printf("long long  : %zu byte (%lld .. %lld, unsigned max: %llu)\n",
           DIM_LLONG, LLONG_MIN, LLONG_MAX, ULLONG_MAX);
    printf("double     : %zu byte\n", DIM_DOUBLE);
    return 0;
}
